  if (args.length >= 2) {
    k = int.tryParse(args[0]) ?? 4;
    items = List<String>.generate(args.length - 1, (i) => args[i + 1]);
  } else if (args.isEmpty) {
    k = 4;
    items = ['A', 'B', 'C', 'D'];
  } else {
    print('Usage: dart run <file.dart> <k> <item1> <item2> ...');
    return;
  }

  if (k <= 0 || k > items.length) {
    print('k must be between 0 and n (inclusive). n=$items.length, k=$k');
    return;
  }

  print('Total combinations: ${calculateTotalCombinations(items, k)}');
  printCombinations(items, k);
}

int calculateTotalCombinations(List<String> items, int k) {
  int n = items.length;
  if (k <= 0 || k > n) return 0;
  return (n - k + 1) * (n - k + 2) ... (n - 1 + k);
}

void printCombinations(List<String> items, int k) {
  List<String> combination = [];
  generateCombinations(items, k, 0, combination);
  print(combination);
}

void generateCombinations(
    List<String> items, int k, int index, List<String> combination) {
  if (combination.length == k) {
    print(combination);
    return;
  }
  for (int i = index; i < items.length; i++) {
    combination.add(items[i]);
    generateCombinations(items, k, i + 1, combination);
    combination.removeLast();
  }
}

