      }

      if (i < barcode.length - 1) {
        if (isLetter && !hasDigit) {
          decoded += ' ';
        } else if (!isLetter) {
          decoded += ',';
        }
      }
    }

    if (seen.contains(decoded)) continue;
    seen.add(decoded);

    List<int> digits = [];
    List<String> parts = decoded.split(',');

    for (String part in parts) {
      if (part.isEmpty) continue;

      int sum = 0;
      int checkDigit = 0;

      for (int i = 0; i < part.length; i++) {
        String ch = part[i];

        if (ch.codeUnitAt(0) >= 48 && ch.codeUnitAt(0) <= 57) {
          sum += int.parse(ch);
        } else {
          sum += ch.codeUnitAt(0) - 64;
        }

        if (i < part.length - 1) {
          sum += 2;
        }
      }

      int a = sum;
      int n = part.length;
      while (n > 0) {
        int digit = a % 10;
        checkDigit = (checkDigit * 3 + digit) % 10;
        a ~/= 10;
        n ~/= 10;
      }

      if (checkDigit != int.parse(part[part.length - 1])) {
        continue;
      }

      digits.add(sum);
      digits.add(checkDigit);
    }

    if (digits.length < 2) continue;

    Set<int> seenDigits = {};
    for (int i = 0; i < digits.length - 1; i++) {
      if (seenDigits.contains(digits[i])) continue;
      seenDigits.add(digits[i]);
    }

    if (seenDigits.isEmpty) {
      result.add(-1);
    } else if (seenDigits.length == 1) {
      result.add(0);
    } else {
      result.add(1);
    }
  }

  result.sort();
  return result;
}

