  for (int t in active) {
    bool worthIt = true;
    for (int prev in visited) {
      if (t == prev) {
        worthIt = false;
        break;
      }
    }
    if (!worthIt) continue;
    visited.add(t);
    int bestPrev = -1;
    for (int prev in active) {
      if (t < prev) break;
      if (prev - t > bestTime) {
        bestPrev = prev;
      }
    }
    if (bestPrev == -1) {
      bestPrev = active[0];
    }
    if (t - bestPrev > bestBin) {
      bestBin = t - bestPrev;
      bestTime = t;
    }
  }
  return [bestBin, bestTime];
}

