void fn0(List<String> args) {



  if (args.length != 1) {
    print('Usage: dart run script.dart <N>');
    return;
  }

  final n = int.parse(args[0]);
  if (n <= 0) {
    print('N must be a positive integer.');
    return;
  }

  const int INF = 1000000;

  final List<List<int>> board = List.generate(n, (_) => List.filled(n, 0));

  int count = 0;

  bool isSafe(int row, int col, List<List<int>> board) {
    for (int i = 0; i < row; i++) {
      if (board[i][col] == 1) return false;
    }
    for (int i = row; i >= 0; i--) {
      if (board[i][col] == 1) return false;
    }
    for (int j = 0; j < n; j++) {
      if (board[row][j] == 1) return false;
    }
    for (int j = n - 1; j >= 0; j--) {
      if (board[row][j] == 1) return false;
    }
    return true;
  }

  bool solve(List<List<int>> board, int row, int col) {
    if (row == n) {
      count++;
      return true;
    }
    for (int c = 0; c < n; c++) {
      if (isSafe(row, c, board)) {
        board[row][c] = 1;
        if (solve(board, row + 1, 0)) return true;
        board[row][c] = 0;
      }
    }
    return false;
  }

  void printBoard(List<List<int>> board) {
    for (final row in board) {
      for (final sq in row) {
        if (sq == 1) {
          print('Q ');
        } else {
          print('. ');
        }
      }
      print('');
    }
    print('');
  }

  if (solve(board, 0, 0)) {
    print('Total solutions: $count');
    printBoard(board);
  } else {
    print('No solution found.');
  }
}

