class Quaternion {
  final double x, y, z, w;

  Quaternion(this.x, this.y, this.z, this.w);

  static Quaternion fromList(List<double> list) {
    if (list.length != 4) {
      throw ArgumentError('Invalid list length for Quaternion');
    }
    return Quaternion(list[0], list[1], list[2], list[3]);
  }

  Quaternion operator +(Quaternion q) {
    return Quaternion(
      x + q.x,
      y + q.y,
      z + q.z,
      w + q.w,
    );
  }

  Quaternion operator -(Quaternion q) {
    return Quaternion(
      x - q.x,
      y - q.y,
      z - q.z,
      w - q.w,
    );
  }

  Quaternion operator *(double d) {
    return Quaternion(x * d, y * d, z * d, w * d);
  }

  Quaternion operator *(Quaternion q) {
    double trace = x + y + z + q.w;
    if (trace == 0.0) {
      return Quaternion(0.0, 0.0, 0.0, 0.0);
    }
    double invTr = 1.0 / trace;
    return Quaternion(
      (x * q.w + q.x * w) * invTr,
      (y * q.w + q.y * w) * invTr,
      (z * q.w + q.z * w) * invTr,
      (q.x * x + q.y * y + q.z * z - w * w) * invTr,
    );
  }

  Quaternion get conjugate => Quaternion(x, y, z, -w);

  double get norm => sqrt(x * x + y * y + z * z + w * w);

  double get angle => 2 * math.acos(norm);

  @override
  String toString() {
    return 'Quaternion($x, $y, $z, $w)';
  }
}

