class Quaternion {
  final double x, y, z, w;

  const Quaternion(this.x, this.y, this.z, this.w);

  const Quaternion(double q)
      : x = q,
        y = 0.0,
        z = 0.0,
        w = 0.0;

  const Quaternion(this.x, this.y, this.z);

  const Quaternion(this.x);

  const Quaternion();

  const Quaternion operator +(other) =>
      Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  const Quaternion operator -(other) =>
      Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  const Quaternion operator *(other) {
    if (identical(other, this)) return this;
    if (other is! Quaternion) return Quaternion(x * other);
    final q = other as Quaternion;
    final realPart = x * q.w + y * q.z + z * q.y + w * q.x;
    final imagPart = y * q.w - x * q.z + z * q.y - w * q.x;
    return Quaternion(realPart, imagPart, z * q.x - y * q.z, w * q.y);
  }

  double norm() => sqrt(x * x + y * y + z * z + w * w);

  const Quaternion conjugate() => Quaternion(x, y, z, -w);

  const Quaternion inverse() =>
      conjugate() * (1.0 / norm().abs()) * norm();

  const Quaternion normalized() =>
      Quaternion(x / norm(), y / norm(), z / norm(), w / norm());

  @override
  String toString() =>
      'Quaternion($x, $y, $z, $w)';
