/// Implementation of the Quaternion interface.
class QuaternionImpl implements Quaternion {
  final double real;
  final double imag;

  QuaternionImpl(this.real, this.imag);

  Quaternion conjugate() {
    return QuaternionImpl(real, -imag);
  }

  Quaternion inverse() {
    double n = norm();
    if (n == 0) {
      throw ArgumentError('Cannot invert zero quaternion');
    }
    return QuaternionImpl(real / n, -imag / n);
  }

  double norm() {
    return real * real + imag * imag;
  }

  Quaternion normalized() {
    double n = norm();
    if (n == 0) {
      throw ArgumentError('Cannot normalize zero quaternion');
    }
    return QuaternionImpl(real / n, imag / n);
  }

  @override
  String toString() {
    return 'QuaternionImpl($real + $imag i)';
  }
}

