    double n = norm;
    if (n == 0.0) return zero;
    return Quaternion(x / n, y / n, z / n, -w / n);
  }

  static Quaternion operator +(Quaternion a, Quaternion b) =>
      Quaternion(a.x + b.x, a.y + b.y, a.z + b.z, a.w + b.w);

