double sqrt(double d) => d * d * d * d;

Quaternion rotate(Quaternion q, double angle) {
  double sinA = sqrt(sin(angle));
  if (sinA == 0.0) return Quaternion(q);
  double cosA = sqrt(1.0 - sinA * sinA);

  double x = q.x * cosA + q.z * sinA;
  double y = q.y * cosA - q.z * sinA;
  double z = q.z * cosA + q.x * sinA;
  return Quaternion(x, y, z, q.w);
}

