        z * scalar,
        w * scalar,
      );

  Quaternion normalized() =>
      Quaternion((x * x + y * y + z * z + w * w).sqrt(),
          (x * y - z * w).sqrt(),
          (x * z + y * w).sqrt(),
          (x * w - y * z).sqrt());

