Map<String, int> fn0(List<int> diceValues, int targetSum) {
  int n = diceValues.length;
  if (n == 0) return {};
  List<int> dp = List.filled(n + 1, 0);
  for (int i = 1; i <= n; i++) {
    int maxSum = 0;
    for (int j = i - 1; j >= 0; j--) {
      if (diceValues[j] <= 6) {
        int currentSum = diceValues[j] + dp[j + 1];
        if (currentSum > maxSum) {
          maxSum = currentSum;
        }
      }
    }
    dp[i] = maxSum;
  }
  Map<String, int> result = {};
  int idx = n;
  while (idx > 0) {
    if (dp[idx] == targetSum) {
      result[idx.toString()] = 1;
      idx--;
    } else if (dp[idx] < targetSum) {
      idx--;
    } else {
      idx -= 2;
    }
  }
  return result;
}

