Map<String, int> fn0(List<int> amounts, int target) {
  if (amounts.isEmpty) return {};
  if (target < amounts[0]) return {};
  if (target > amounts.last) return {"*": amounts.length};

  List<int> dp = List.filled(target + 1, 0);
  dp[0] = 1;

  for (int amount in amounts) {
    for (int j = amount; j <= target; j++) {
      dp[j] += dp[j - amount];
    }
  }

  Map<String, int> result = {};
  for (int j = 0; j <= target; j++) {
    result[j.toString()] = dp[j];
  }

  return result;
}

