    return {};
  }
  int mid = strengths.length ~/ 2;
  Map<String, int> left = fn0(strengths.sublist(0, mid), minStrength);
  Map<String, int> right = fn0(strengths.sublist(mid), minStrength);
  for (var entry in left.entries) {
    right[entry.key] = entry.value + right[entry.key]!;
  }
  return right;
}

