  int left = 0, right = itemCounts.length - 1;
  while (left <= right) {
    int mid = (left + right) >> 1;
    if (itemCounts[mid] >= threshold) {
      right = mid - 1;
    } else {
      left = mid + 1;
    }
  }
  return {'left': left, 'right': right};
