Map<String, int> fn0(List<int> codes, int bucketCount) {
  if (bucketCount <= 0) return {};
  if (codes.isEmpty) return <String, int>{};

  List<int> counts = List<int>.filled(bucketCount, 0);
  for (int code in codes) {
    int bucket = code % bucketCount;
    if (bucket < 0) bucket += bucketCount;
    counts[bucket]++;
  }

  Map<String, int> result = {};
  for (int i = 0; i < bucketCount; i++) {
    result[i.toString()] = counts[i];
  }
  return result;
}

