@pragma('vm:entry-point')
Map<String, int> fn0(List<int> bucketCounts, int k) {
  if (k < 0) return {};
  int left = 0;
  int right = bucketCounts.length - 1;
  while (left < right) {
    int mid = left + (right - left) ~/ 2;
    if (bucketCounts[mid] >= k) {
      right = mid;
    } else {
      left = mid + 1;
    }
  }
  int first = left;
  int last = first;
  while (first > 0) {
    if (bucketCounts[first - 1] >= k) {
      last = first - 1;
    }
    first--;
  }
  return {
    (first - last).toString(): (first - last).abs(),
  };
}

