Map<String, int> fn0(List<int> packetSizes, int mtu) {
  if (packetSizes.isEmpty) return {};
  int n = packetSizes.length;
  List<int> dp = List.filled(n + 1, mtu);
  for (int i = 0; i < n; i++) {
    int size = packetSizes[i];
    if (size <= mtu) {
      dp[i + 1] = dp[i] - size + 1;
    }
    for (int j = i - 1; j >= 0; j--) {
      int len = dp[j] + 1;
      if (packetSizes[j] <= size && len > dp[i + 1]) {
        dp[i + 1] = len;
      }
    }
  }
  Map<String, int> result = {};
  int count = 0;
  int current = dp[n];
  while (current > 0) {
    result[count.toString()] = current;
    count++;
    current -= 1;
  }
  return result;
}

