  if (cards.isEmpty) return {};
  int left = 0;
  int sum = 0;
  for (int right = 0; right < cards.length; right++) {
    sum += cards[right];
    while (sum > targetSum && left <= right) {
      sum -= cards[left];
      left++;
    }
    if (sum == targetSum) {
      Map<String, int> result = {};
      result[left.toString()] = right.toString();
      result[right.toString()] = left.toString();
      return result;
    }
  }
  return {};
}

