  bool kmpSearch(String text, String pattern) {
    int n = text.length;
    int m = pattern.length;

    if (m > n) return false;

    List<bool> lps = List<bool>.filled(m + 1, false);
    int len = 0; 
    int i = 1;

    lps[0] = true;

    while (i < m) {
      if (pattern[i] == pattern[len]) {
        len++;
        lps[i] = true;
        i++;
      } else {
        if (len != 0) {
          len = lps[len - 1];
        } else {
          lps[i] = false;
          i++;
        }
      }
    }

