          break;
        }
      }

      if (found) {
        count++;
        lo = mid + 1;
      } else {
        hi = mid - 1;
      }
    }

    return count > 0;
  }

  print("Text: $text");
  print("Pattern found at indices: ${kmpSearch(text, pattern)}");

