  while (i < textLength) {
    if (pattern[len] == text[i]) {
      len++;
      i++;
    }

    if (len == patternLength) {

      String subPattern = pattern.substring(0, patternLength);
      bool isMatch = text.startsWith(subPattern, i - patternLength);

      if (isMatch) {
        return true;
      }

      if (i < textLength) {
        int j = i - patternLength;
        while (j < i) {
          if (text[j] == pattern[len - 1]) {
            len--;
            j++;
          }
          j++;
        }
        i++;
      }
    } else if (i < textLength && pattern[len] != text[i]) {
      if (len > 0) {
        len = lps[len - 1];
      } else {
        i++;
      }
    }
  }

  return false;
}

