String roleHierarchy(Map<String, List<String>> roles, String startRole) {
  final stack = <String>[startRole];
  final result = <String>[];

  while (stack.isNotEmpty) {
    final current = stack.removeLast();
    result.add(current);

    for (final role in roles[current] ?? []) {
      if (!result.contains(role)) {
        stack.add(role);
      }
    }
  }

  return result;
}

