    return value.toRadixString(16).toUpperCase().padLeft(8, '0');
  }

  String byteToHex(int value) {
    return value.toRadixString(16).padLeft(2, '0');
  }

  print('Original value: 0x${intToHex(value)}');

  int swapped = value;
  int bits = 32;
  while (bits > 0) {
    swapped = (swapped >> 1) ^ ((swapped & 1) << (bits - 1));
    bits >>= 1;
  }

  print('32-bit swap of 0x${intToHex(value)}: 0x${intToHex(swapped)}');

  final int little = 0x12345678;

  String littleIntToHex(int value) {
    return value.toRadixString(16).toUpperCase().padLeft(8, '0');
  }

  String littleByteToHex(int value) {
    return value.toRadixString(16).padLeft(2, '0');
  }

  print('Original 16-bit values: [0x${littleByteToHex(little & 0xFF)}, 0x${littleByteToHex((little >> 8) & 0xFF)}]');

  int littleSwapped = little;
  bits = 16;
  while (bits > 0) {
    littleSwapped = (littleSwapped >> 1) ^ ((littleSwapped & 1) << (bits - 1));
    bits >>= 1;
  }

  print('16-bit swap of 0x${littleIntToHex(little)}: 0x${littleIntToHex(littleSwapped)}');

  final double doubleValue = 3.14159;

  List<int> doubleToBytesLE(double value) {
    final bytes = List.filled(8, 0);
    for (int i = 0; i < 8; i++) {
      final int byte = value * 256;
      bytes[i] = byte.round();
    }
    return bytes;
  }

  List<int> doubleToBytesBE(double value) {
    final bytes = List.filled(8, 0);
    for (int i = 0; i < 8; i++) {
      final int byte = value * 256;
      bytes[i] = ((byte >> 24) & 0xFF) |
                  ((byte >> 16) & 0xFF) |
                  ((byte >> 8) & 0xFF) |
                  (byte & 0xFF);
    }
    return bytes;
  }

  print('Float value: ${doubleValue.toStringAsFixed(2)}');
  print('As Little Endian bytes: [${doubleToBytesLE(doubleValue).map((b) => b.toRadixString(16).padLeft(2, '0')).join(' ')}]');
