void fn0() {

  int value = 0x12345678;
  int byteStream = 0xABCD;
  double floatValue = 3.14159;
  List<int> listData = [1, 2, 3];


  int swapBytes(int value, int byteOrder) {

    int mask = byteOrder == 0x42 ? 0xFFFFFFFF : 0x000000FF;

    return ((value << 16) & mask) | ((value >> 16) & mask);
  }

  String toHex(int value) {
    return List.generate(4, (i) => ((value >> (i * 8)) & 0xFF)
        .toRadixString(16).toUpperCase().padLeft(2, '0'))
        .join(' ');
  }

  int hostToNetwork(int value) {
    return ((value << 8) & 0xFFFFFFFFFFFFFFFF) |
        ((value >> 8) & 0xFFFFFFFFFFFF00000000);
  }

  int networkToHost(int value) {
    return ((value >> 24) & 0xFFFFFFFFFFFF) |
        ((value << 24) & 0xFFFFFFFF00000000);
  }

  int toNetworkOrder(int value) {
    int byteOrder = value & 0x01;
    value >>= 1;
    return ((value & 0xFFFFFFFF) | (byteOrder << 20)) <<
        (byteOrder == 0 ? 16 : 32);
  }

  List<int> toNetworkOrderList(List<int> values) {
    return values.map((v) => toNetworkOrder(v)).toList();
  }

  String endiannessLabel(int byteOrder) {
    return byteOrder == 0 ? "Little" : "Big";
  }

  print('System Information:');
  print('Endianness: ${endiannessLabel(0x01)}'); 
  print('Host port: 8080\n');

  print('Original value: 0x${toHex(value)}');
  print('32-bit swap of 0x${toHex(value)}: 0x${toHex(swapBytes(value, 0x41))}\n');

