  print('Network bytes: [${toHex(networkValue & 0xFFFF)}, ${toHex((networkValue >> 16) & 0xFFFF)}]');
  print('Reconstructed: [${toHex((networkValue & 0xFFFF)}, ${toHex((networkValue >> 16) & 0xFFFF)})]');
