  final frequentItemsetSupport = <Set<String>, double>{};

  while (transactionsWithSupport.isNotEmpty) {
    final itemset = transactionsWithSupport.removeLast();

    if (itemset.length <= 1) {
      frequentItemsets.add(itemset);
      frequentItemsetSupport[itemset] = 1.0;
      continue;
    }

    final candidateKeys = itemset.toSet().where((e) => frequentItemsetSupport[e] == 1.0).toList();
    final k = candidateKeys.length;

    for (final candidate in candidateKeys) {
      final remaining = transactionsWithSupport.where((t) => t.contains(candidate)).toList();

      if (remaining.isEmpty) {
        frequentItemsetSupport[candidate] = 0.0;
      } else if (remaining.length == 1) {
        frequentItemsetSupport[candidate] = frequentItemsetSupport[remaining[0]]!;
      } else {

        final newFpGrowth = <Set<String>>[];
        final newFpGrowthSupport = <Set<String>, double>{};

        for (final remainingTransaction in remaining) {
          for (final item in remainingTransaction) {
            if (!newFpGrowth.contains(item)) {
              newFpGrowth.add(item);
              newFpGrowthSupport[item] = frequentItemsetSupport[remainingTransaction]!;
            }
          }
        }

