        if (maxSupport == null) {
          frequentItemsetSupport[candidate] = 0.0;
        } else {
          frequentItemsetSupport[candidate] = maxSupport.key.length / candidate.length;
        }

        newFpGrowth.remove(candidate);
        newFpGrowthSupport[candidate] = 0.0;

        for (final item in maxSupport.key) {
          if (newFpGrowth.contains(item)) {
            for (final other in newFpGrowth) {
              if (other == item) continue;
              if (other.contains(item)) {
                newFpGrowthSupport[item] = (newFpGrowthSupport[item] ?? 0.0) + frequentItemsetSupport[other]!;
              }
            }
          }
        }

        for (final item in newFpGrowth) {
          newFpGrowthSupport[item] = (newFpGrowthSupport[item] ?? 0.0) + frequentItemsetSupport[other]!;
        }

        newFpGrowth.addAll(newFpGrowthSupport.entries.where((e) => e.value >= support).toList());
      }
    }

    frequentItemsets.add(itemset);
    frequentItemsetSupport[itemset] = 1.0;
  }

