        halfHeight = side / 2;

  Rectangle.random(
      double maxX, double maxY, Random random, int k) {
    final points = <Point>[];
    while (points.length < k) {
      final point = Point.random(maxX, maxY, random);
      if (points.isEmpty || points.last != point) points.add(point);
    }
    return Rectangle(centerX: points[0].x,
        centerY: points[0].y,
        halfWidth: (points[1].x - points[0].x) / 2,
