class Rectangle {
  final double x;
  final double y;
  final double width;
  final double height;

  Rectangle(
    this.x,
    this.y,
    this.width,
    this.height,
  );

  Rectangle.square(double centerX, double centerY, double side)
      : this(centerX, centerY, side, side);

  Rectangle.fromPoints(Point p1, Point p2)
      : this(p1.x, p1.y, p2.x - p1.x, p2.y - p1.y);

  bool contains(Point p) =>
      p.x >= x &&
      p.x <= x + width &&
      p.y >= y &&
      p.y <= y + height;

  bool overlaps(Rectangle other) =>
      !(other.x - x > width ||
          other.x - x < -width ||
          other.y - y > height ||
          other.y - y < -height);

  Rectangle union(Rectangle other) =>
      Rectangle.fromPoints(
        Point(x < other.x ? x : other.x, y < other.y ? y : other.y),
        Point(
          x < other.x ? other.x : x + width,
          y < other.y ? other.y : y + height,
        ),
      );

  Rectangle intersection(Rectangle other) =>
      Rectangle.square(
        (x < other.x ? x : other.x) + ((x < other.x ? other.x : x) - x) / 2,
        (y < other.y ? y : other.y) + ((y < other.y ? other.y : y) - y) / 2,
        other.width > width ? other.width : width,
        other.height > height ? other.height : height,
      );

  Rectangle translate(double dx, double dy) =>
      Rectangle(x + dx, y + dy, width, height);

  Rectangle resize(double dx, double dy) =>
      Rectangle(x, y, dx, dy);

  Rectangle resizeFromCenter(double centerX, double centerY, double newWidth,
      double newHeight) =>
      Rectangle.square(centerX, centerY, newWidth);

  Rectangle resizeToFit(Rectangle other) =>
      Rectangle.resizeFromCenter(
        x, y, other.width, other.height,
      );

  Rectangle get boundingBox =>
      Rectangle(x - width, y - height, width * 2, height * 2);

  Rectangle get center =>
      Rectangle(x + width / 2, y + height / 2, width / 2, height / 2);

  Rectangle get half =>
      Rectangle(x + width / 4, y + height / 4, width / 2, height / 2);

  @override
  String toString() => 'Rectangle(center: ($x, $y), halfWidth: $width / 2, halfHeight: $height / 2)';
}

