    for (int i = 0; i < cluster.length; i++) {
      for (int j = i + 1; j < cluster.length; j++) {
        double dist = distance(cluster[i], cluster[j]);
        if (dist <= threshold) {

          List<double> newCentroid = List.from(centroid);
