    [3.5, 1.0],
    [4.0, 4.5],
  ];

  final n = points.length;

  List<List<double>> centroids = List.generate(k, (_) => List.filled(points.length, 0.0));

  for (int i = 0; i < points.length; i++) {
    final randIndex = rand.nextInt(k);
    centroids[randIndex] += points[i];
  }

  for (int iter = 0; iter < iterations; iter++) {

    final newCentroids = <List<double>>[];

    for (int j = 0; j < k; j++) {
      newCentroids.add(<double>[0.0, 0.0]);
    }

    for (int i = 0; i < points.length; i++) {

      double minDist = double.infinity;
      int bestCluster = -1;

      for (int j = 0; j < k; j++) {
        final d = points[i][0] - centroids[j][0];
        final d2 = points[i][1] - centroids[j][1];
        final dist = d * d + d2 * d2;
        if (dist < minDist) {
          minDist = dist;
          bestCluster = j;
        } else if (dist == minDist) {

          if (rand.nextDouble() < minDist / d2) {
            bestCluster = j;
          }
        }
      }

      newCentroids[bestCluster] += points[i];
    }

    for (int j = 0; j < k; j++) {
      for (int d = 0; d < 2; d++) {
        newCentroids[j][d] /= points.length;
      }
    }

    bool changed = false;

    for (int j = 0; j < k; j++) {
      for (int d = 0; d < 2; d++) {
        if (newCentroids[j][d] != centroids[j][d]) {
          changed = true;
        }
      }
    }

    if (!changed) {
      break;
    }

    centroids = newCentroids;
  }

  print('Converged in $iter iteration(s).');

  for (int j = 0; j < k; j++) {
    final cluster = <List<double>>[];
    for (int i = 0; i < points.length; i++) {
      if (centroids[j][0] - eps < points[i][0] && points[i][0] < centroids[j][0] + eps) {
        if (centroids[j][1] - eps < points[i][1] && points[i][1] < centroids[j][1] + eps) {
          cluster.add(points[i]);
        }
      }
    }
    print('Cluster $j: ${cluster.length} points: ${cluster.map((p) => p.join(',')).join(', ')}');
  }
}

