    for (int i = 0; i < a.length; i++) {
      final diff = a[i] - b[i];
      sum += diff * diff;
    }
    return sqrt(sum);
  }

  int centroidIdx(List<double> point) {
    int bestIdx = 0;
    double bestDist = distance(point, centroids[0]);
    for (int i = 1; i < k; i++) {
      final dist = distance(point, centroids[i]);
      if (dist < bestDist) {
        bestDist = dist;
        bestIdx = i;
      }
    }
    return bestIdx;
  }

  final List<Set<int>> clusters = List<Set<int>>.generate(k, (_) => <int>{});

  final List<List<double>> points = List<List<double>>.generate(n, (i) => List<double>.from(data[i]));

